    "code": "// per-level phase derivative (parent-coupled)\nlet parent = 0;\nfor (let k = 0; k < L; k++) {\n  out[k] = om[k] * (1 + eps * Math.sin(parent));\n  parent = x[k];\n}\n\n// per-level angular frequency (precomputed each step)\nfor (let k = 0; k < L; k++)\n  this.omega[k] = w0 * Math.pow(sf, k) * IRRATIONAL_DRIVERS[k % IRRATIONAL_DRIVERS.length];\n\n// nested epicycle position\nlet amp = 1, prev = 0;\nfor (let k = 0; k < L; k++) {\n  const th = st[so + k];\n  x += amp * Math.cos(th);\n  y += amp * Math.sin(th);\n  z += amp * Math.sin(th - prev);\n  prev = th; amp *= aScale;\n}",
